// a 50 x 30 plate drawn by hand and then dimensioned, 6 thick
const sk = sketch('top')
const plate = sk.rectangle([0.4, 0.3], [48, 31])
const big = sk.circle([34, 14], { r: 4.6 })
sk.at(plate.bottom.a, [0, 0])
sk.length(plate.bottom, 50)
sk.length(plate.right, 30)
sk.diameter(big, 10)
sk.dx(plate.bottom.a, big.c, 35)
sk.dy(plate.bottom.a, big.c, 15)
const part = extrude(sk, 6)
hole(part, { across: 4, at: [-15, 0] })
chamfer(part.edge('top', 'right'), 1)

// a small parts tray with one screw hole in the middle
const b = box(80, 50, 30)
hole(b, { across: 4, countersink: { across: 8, angle: 90 } })
hollow(b, { wall: 2, open: 'top' })

